-- 0249_medication_is_thistles_competency_assessment
-- The Medication Competency Assessment was the worst of the imports, and the damage was
-- not cosmetic:
--
--   * THE PAGE OF GUIDANCE BECAME A QUESTION. The whole "Competency Assessment Tool" essay
--     -- who may administer medicines, how to use the tool, what to do when something
--     cannot be observed -- was imported as a single_select with Yes and No against it. The
--     instructions for the assessment were a question in the assessment.
--   * A QUESTION LOST ITS QUESTION. "Record Keeping" arrived as a bare Yes/No field labelled
--     "Record Keeping". The actual question -- did the member of staff sign the MAR chart
--     immediately after administering -- was eaten by the section heading it was glued to.
--     Signing the MAR is the single most auditable act in the whole assessment.
--   * TWO QUESTIONS WERE MISSING ENTIRELY: witnessing the PPE change before administration,
--     and who is responsible for obtaining the medication.
--   * "Was the medication selected checked against the correct MAR chart" was a TEXT BOX,
--     so the one question that catches giving the right drug to the wrong person could be
--     answered with anything at all, or a space.
--   * One question offered "yes", "no" and "option_3".
--   * Completed By was in there twice, both required.
--
-- NOT SEEN THIS TIME, ON EVERY OBSERVED ACTION (Phil, 2026-09-08). Thistle's guidance says
-- that where something cannot be observed -- no creams prescribed that day -- the assessor
-- records "none seen this time" rather than a fail. The import gave that option to eight
-- questions and not the other fifteen, with no pattern to it, so an assessor with nothing to
-- observe had to answer No, which reads as the carer getting it wrong. Every observed action
-- now offers it. The knowledge questions -- can they describe an error, do they know who to
-- ring -- stay Yes/No, because those can always be asked.
--
-- NO TRAINING STOPS THE ASSESSMENT (Phil, 2026-09-08: "stop, and the check stays due").
-- The paper form says so in words -- "if no, please stop competency assessment until
-- completed" -- and words in a box stop nobody. It is now a stand down gate: answer No and
-- the remaining thirty questions grey out and store nothing. The Evidence is kept, because
-- an assessment attempted and stopped is worth recording, but the check is NOT advanced.
-- An untrained carer must not appear on the matrix as competency assessed for the year.
--
-- DROPPED as givens: Name, Region, Completed By (twice), and the two signature dates -- the
-- Evidence stamps who submitted it and when. Date of Next Assessment goes the same way as
-- the Manual Handling one: the check schedules it 365 days after the assessment date, so a
-- hand-typed "above date plus 1 year" could only ever disagree with it.
--
-- THE OUTCOME IS PICKED, NOT WRITTEN. Thistle's three numbered outcomes (competent /
-- competent with exceptions / further supervision required) were imported as a free text
-- box, so the one line an inspector reads first was whatever somebody typed. They are now
-- the three options, and "Actions and exceptions identified" is asked -- and required --
-- only for the two outcomes that have exceptions to name.
--
-- Replaced IN PLACE at version 1 across the master template and both company copies. No
-- Medication CA evidence exists anywhere; the guard enforces that rather than trusting
-- this note.
-- Applied to the becarecompliant project ONLY (ref bgrtcvyjuwopunpnudeu).

do $$
declare
  v_schema jsonb := '{"schemaVersion": 1, "sections": [{"id": "assessment", "title": "The assessment", "fields": [{"key": "assessment_date", "type": "date", "label": "Date of competency assessment", "required": true, "help": "The next assessment falls due a year after this date."}], "description": "Medicines may only be administered by staff who have completed medication training. The assessor accompanies the member of staff to a service user''s property and watches them work as if they were alone, ready to step in if unsafe practice is about to happen. Any No must be resolved before that person administers medication unsupervised. Repeat yearly, or sooner if something indicates it - a medication error, for instance. This tool does not assess invasive or specialised techniques; those belong to the appropriate healthcare professional."}, {"id": "training", "title": "Training and policy", "fields": [{"key": "policy_access", "type": "single_select", "label": "Does the member of staff know how to access or request the medication policy if they wish to check any information?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true}, {"key": "medication_training", "type": "single_select", "label": "Has the member of staff completed training on the safe handling and administration of medications?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true, "help": "If no, the assessment stops here and the rest of the form is closed. Make sure the carer is not allocated to any calls that require medication administration until the training is completed. The check stays due, because they have not been assessed.", "standsDown": {"when": ["no"]}}]}, {"id": "hygiene", "title": "Preparation and hygiene", "fields": [{"key": "hands_washed", "type": "single_select", "label": "Did the member of staff wash their hands before starting to administer medication?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "ppe_changed", "type": "single_select", "label": "Did you witness the member of staff change their PPE (gloves) prior to medication administration?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "cream_gloves", "type": "single_select", "label": "If prescription creams are required, did the member of staff wear gloves when applying them?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true, "help": "Non prescription creams (Nivea, cocoa butter and the like) must be written in the Council care plan. If they are not, stop the member of staff applying them and ask the office to speak to the social worker for an updated care plan."}], "description": "Where something could not be observed - no creams prescribed that day, say - answer Not seen this time. It may still be possible to assess it by asking what they would do, and to record that they may administer everything except the part not witnessed, until it can be seen."}, {"id": "consent", "title": "Consent", "fields": [{"key": "consent", "type": "single_select", "label": "Did the member of staff gain consent from the individual prior to administering medication or applying cream?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}]}, {"id": "selection", "title": "Selection and preparation", "fields": [{"key": "read_mar", "type": "single_select", "label": "Before selecting, preparing or administering medication, did the member of staff read the MAR chart accurately?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "prescription_label", "type": "single_select", "label": "Before administering, did the member of staff check that the medication or cream had a prescription label?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "cream_site", "type": "single_select", "label": "Before applying any prescribed creams, did the member of staff check where the cream should be applied as per the prescription label?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "already_given", "type": "single_select", "label": "Did the member of staff check whether medication had already been administered, or had been discontinued?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "unclear_directions", "type": "single_select", "label": "If any directions were unclear or illegible on the MAR, did the member of staff take appropriate steps to clarify them?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "checked_against_mar", "type": "single_select", "label": "Was the medication selected checked against the correct MAR chart, including the person''s name on both the label and the MAR?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "directions_differ", "type": "single_select", "label": "If the directions on the MAR chart differed from those on the label, did the member of staff satisfy themselves as to the correct dose to be given?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true, "help": "For example, contacting the branch office for advice or contacting the GP."}, {"key": "correct_dose_time", "type": "single_select", "label": "Was the correct medication and dose selected at the correct time, with consideration given to food or other directions on the label?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true, "help": "Where medication is given at more than one call a day, consider the gap between them - is there more than four hours between the morning and lunch calls?"}, {"key": "prepared_per_mar", "type": "single_select", "label": "Was the medication prepared according to the directions and information on the MAR chart, or any accompanying protocol?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}]}, {"id": "administration", "title": "Administration", "fields": [{"key": "support_dignity", "type": "single_select", "label": "Did the member of staff offer information, support and reassurance throughout, in a manner which encourages co-operation, promotes dignity and is appropriate to the person''s needs and concerns?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "administered_correctly", "type": "single_select", "label": "Was the medicine administered correctly, and a glass of water offered where appropriate?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "witnessed_taking", "type": "single_select", "label": "Did the member of staff visually witness the individual taking all their medication?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "left_out_checked", "type": "single_select", "label": "If medication was to be left out for the service user, did the member of staff check the medication assessment to make sure that was safe?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "not_taken_response", "type": "single_select", "label": "If the medication was not taken, did the member of staff respond as per the medication policy?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true, "help": "For example, using the correct key on the MAR chart and reporting it to the local office."}, {"key": "not_taken_advice", "type": "single_select", "label": "If the medication was not taken, was medical advice sought and documented?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "low_stock_reported", "type": "single_select", "label": "If the member of staff used the last dose, or the medication was running low, did they report it to their local office or a family member?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "who_responsible", "type": "short_text", "label": "Who is responsible for obtaining the medication?", "help": "For example the family, or a repeat prescription.", "validation": {"maxLength": 200}}]}, {"id": "record_keeping", "title": "Record keeping", "fields": [{"key": "signed_mar", "type": "single_select", "label": "Did the member of staff sign the MAR chart immediately after the medication was administered?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}, {"key": "recorded_in_notes", "type": "single_select", "label": "Did the member of staff record the medication administration, or application of creams, in the daily report notes?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}]}, {"id": "storage", "title": "Storage", "fields": [{"key": "storage_conditions", "type": "single_select", "label": "Is the member of staff aware of the correct storage conditions for medicines, and where to find that information?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true, "help": "For example the prescription label, or the medication assessment."}, {"key": "locked_box", "type": "single_select", "label": "If the medication was to be stored in a locked box, did the member of staff check that this was assessed in the medication assessment?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}, {"value": "not_seen", "label": "Not seen this time"}], "required": true}]}, {"id": "advice", "title": "Advice and information", "fields": [{"key": "who_to_contact", "type": "single_select", "label": "Does the member of staff know who to contact if they need advice on medication?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true, "help": "For example NHS Direct, the GP, or their local office."}, {"key": "aware_of_plan_info", "type": "single_select", "label": "Is the member of staff aware of the information the service delivery plan and medication assessment provide when looking for medication information?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true}]}, {"id": "errors", "title": "Errors", "fields": [{"key": "own_error", "type": "single_select", "label": "Can the member of staff describe the correct process for what to do if they make an error?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true}, {"key": "others_error", "type": "single_select", "label": "Can the member of staff describe the correct process for what to do if they discover an error made by another member of staff?", "options": [{"value": "yes", "label": "Yes"}, {"value": "no", "label": "No"}], "required": true}]}, {"id": "outcome", "title": "Outcome of assessment", "fields": [{"key": "any_other_information", "type": "long_text", "label": "Any other information", "help": "Any questions or discussions had with the member of staff.", "validation": {"maxLength": 2000}}, {"key": "outcome", "type": "single_select", "label": "Considering everything gathered during this assessment, the member of staff has been assessed as", "required": true, "options": [{"value": "competent", "label": "Demonstrated competence, able to administer medication unsupervised"}, {"value": "competent_with_exceptions", "label": "Mostly demonstrated competence, able to administer medication unsupervised except for the tasks below"}, {"value": "further_required", "label": "Further supervision or training is required before administering medication unsupervised"}]}, {"key": "actions_exceptions", "type": "long_text", "label": "Actions and exceptions identified", "required": true, "validation": {"maxLength": 2000}, "visibleWhen": {"field": "outcome", "in": ["competent_with_exceptions", "further_required"]}, "help": "What they may not do unsupervised yet, and what has to happen before they can."}]}, {"id": "sign_off", "title": "Sign off", "fields": [{"key": "assessor_signature", "type": "signature", "label": "Assessor''s declaration", "required": true, "help": "I confirm that this is an accurate and true record of the assessment."}, {"key": "team_member_signature", "type": "signature", "label": "Team member signature"}]}]}'::jsonb;
  v_blocked int;
begin
  select count(*) into v_blocked
    from public.evidence e
    join public.form_versions fv on fv.id = e.form_version_id
    join public.forms f on f.id = fv.form_id
   where f.key = 'medication_ca';

  if v_blocked > 0 then
    raise exception 'Medication CA has % pieces of evidence against it; delete the test evidence or publish a new version', v_blocked;
  end if;

  update public.form_templates
     set schema = v_schema,
         name = 'Medication Competency Assessment',
         updated_at = now()
   where key = 'medication_ca';

  update public.form_versions fv
     set schema = v_schema
    from public.forms f
   where f.id = fv.form_id
     and f.key = 'medication_ca'
     and fv.version = 1;

  update public.forms
     set name = 'Medication Competency Assessment',
         updated_at = now()
   where key = 'medication_ca';
end $$;
